if ~exist('src800','var')
    src800 = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align.sqw');
end
if ~exist('src800sym','var')
    src800sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align_sym3.sqw');
end
hc = hor_config;
ll = 2;
hc.log_level = -2;

w2_000a = cut(src800,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);lz 0 1;liny;keep_figure; %[output:12e1f6cc]
%w2_000b = cut(src800,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
%plot(w2_000b);lz 0 1; keep_figure;

%w2_001 = cut(src800,line_proj('offset',[0,0,1]),0.04,0.04,[-0.1,0.1],[95,105]);
%plot(w2_001);lz 0 1; keep_figure;

w2_00 = cut(src800,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; %[output:0581f1d3]
keep_figure; %[output:0581f1d3]
w2_00s = cut(src800sym,line_proj(),0.03,0.03,[-0.1,0.1],[95,105]);
plot(w2_00s);lz 0 1; %[output:0c31c3ca]
keep_figure; %[output:0c31c3ca]

hc.log_level = ll;
%%

other_ranges800 = {[-0.1,0.1],[-0.1,0.1],[0,4,600]};
%
% recover masks not to draw them again
[mask2fit800GH,mask_res_file800GH]  = recover_selected_cuts('mask2fit800GH','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[GH_FFCutsFits,allJfitfileGH] = recover_selected_cuts('GH_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

file = src800.full_filename %[output:418d6111]
[~,fname800] = fileparts(file);
%%

% check form factor for <200> cuts in <0,0,1> direction
hc.log_level = -2;

lp010off110 = line_proj([0,0,1],[1,0,0],'offset',[0,2,0]);
w2_800sm = cut(src800sym,lp010off110,[0,0.04,2],other_ranges800{:},SymopRotation([0,0,1],90,[0,0,0]));
fh = plot(w2_800sm);liny; lz 0 2; %[output:014baeaa]
[w2_800sm,masks2fit800GH]= draw_masks_helper(fh,masks2fit800GH,'msk_dir001off020',2); %[output:9450e575]
plot(w2_800sm); lz 0 1;keep_figure
hc.log_level = ll;
%%
w2_800ort = cut(w2_800sm,[0,0.02,1],[40,2,220])
plot(w2_800ort); lz 0 1;keep_figure
GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off020GH001minFF', ...
    w2_800ort);
%%
% Radial cuts along axis <200> offset. Max FF change, Minimal and maximal
% FF value
hc.log_level = -2;

lp010of020 = line_proj([0,1,0],[-1,0,0],'offset',[0,2,0]);
w2_800dir010of020 = cut(src800sym,lp010of020,[-2,0.04,2],other_ranges800{:});
w2_800dir010of020.full_filename = [fname800,', w2_800dir010of020'];
fh=plot(w2_800dir010of020); lz 0 0.5; %[output:31afaaf8]
[w2_800dir010of020,mask2fit800GH]= draw_masks_helper(fh,mask2fit800GH,'msk_Ei800dir010off020',2);
plot(w2_800dir010of020); lz 0 0.5;keep_figure; %[output:31afaaf8]

lp100of200 = line_proj([1,0,0],[0,1,0],'offset',[2,0,0]);
w2_800dir100of200 = cut(src800sym,lp100of200,[-2,0.04,2],other_ranges800{:});
w2_800dir100of200.full_filename = [fname800,', w2_800w2_800dir100of200'];
fh = plot(w2_800dir100of200 ); lz 0 0.5; %[output:7f869c76]
[w2_800dir100of200,mask2fit800GH]= draw_masks_helper(fh,mask2fit800GH,'msk_Ei800dir100off200',2);
plot(w2_800dir100of200); lz 0 0.5;keep_figure; %[output:7f869c76]
%
w2e800dir100of200mimaxFF = sqw_op_bin_pixels({w2_800dir010of020,w2_800dir100of200}, ...
    @move_all_to_proj, ...
    {[lp010of020,lp100of200]}, ...
    lp010of020,[-1,0.04,1],other_ranges800{:},'-combine');
plot(w2e800dir100of200mimaxFF);liny; lz 0 0.5;keep_figure; %[output:9fcc433f]
%%
% cuts in <010> direction offset 020 -- max FF change, max dE cut along
% axis
w2ei800off020dir010maf = cut(w2e800dir100of200mimaxFF,[0,0.04,1],[80,4,400]) %[output:254bc7b4]
plot(w2ei800off020dir010maf); lz 0 0.3;keep_figure; %[output:076c521c]

GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off200GHmaxFF',w2ei800off020dir010maf);
%%

w2ei800off020dir010mif = cut(w2e800dir100of200mimaxFF,[-1,0.04,0],[80,4,240]) %[output:097ede5c]
w2ei800off020dir010mif = cut(w2ei800off020dir010mif,[0,0.04,1],[80,4,240], ...
    SymopReflection('normvec',[0,1,0],'offset',[0,2,0]));
plot(w2ei800off020dir010mif); lz 0 0.5;keep_figure; %[output:616d53d8]
GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off200GHminFF',w2ei800off020dir010mif);


%%
% cuts in <010> direction offset 110 -- min/max FF change,
%
% w2_800b = cut(src800sym,line_proj([0,1,0],[-1,0,0],'offset',[1,1,0]),[-1,0.04,2],other_ranges800{:});
% w2_800b.full_filename = [fname800,', w2_800b'];
% plot(w2_800b); lz 0 0.5;keep_figure;
% w2_800b1 = cut(src800sym,line_proj([1,0,0],[0,1,0],'offset',[1,1,0]),[-1,0.04,2],oother_ranges800{:});
% w2_800b1.full_filename = [fname800,', w2_800b1'];
% plot(w2_800b1); lz 0 0.5;keep_figure;

w2_800of110dir010 = cut(src800sym,line_proj([0,1,0],[-1,0,0],'offset',[1,1,0]),[-1,0.04,2],other_ranges800{:}, ...
    SymopRotation([0,0,1],90,[1,1,0]));
w2_800of110dir010.full_filename = [fname800,', w2_800om1m1'];
fh = plot(w2_800of110dir010); lz 0 0.5; %[output:280b097f]
[w2_800of110dir010,mask2fit800GH]= draw_masks_helper(fh,mask2fit800GH,'msk_Ei800dir010off110',1);
plot(w2_800of110dir010); lz 0 0.5;keep_figure; %[output:280b097f]
%%
% cuts in <010> direction offset 110 -- min/max FF change,
w2_800of110dir010maf = cut(w2_800of110dir010,[0,0.04,1],[80,4,300]) %[output:80b2e73f]
plot(w2_800of110dir010maf); lz 0 0.3;keep_figure; %[output:5bbb1861]

GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off110GHmaxFF',w2_800of110dir010maf);
%%

w2ei800off020dir010mif = cut(w2_800of110dir010,[-1,0.04,0],[80,4,195]) %[output:808cc5e7]
w2ei800off020dir010mif = cut(w2ei800off020dir010mif,[0,0.04,1],[80,4,195], ...
    SymopReflection('normvec',[0,1,0],'offset',[1,1,0]));
plot(w2ei800off020dir010mif); lz 0 0.5;keep_figure; %[output:6701e8ee]
GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off110GHminFF',w2ei800off020dir010mif);

%%
% cuts in <010> direction offset 020 -- change orthogonal to axis; medium
% ff change
lp010of200 = line_proj([0,1,0],[-1,0,0],'offset',[2,0,0]);
w2_800dir010off200  = cut(src800sym,lp010of200,[0,0.04,2],other_ranges800{:});
w2_800dir010off200.full_filename = [fname800,', w2_800dir010off200'];
fh=plot(w2_800dir010off200); lz 0 1; %[output:9c810b22]
[w2_800dir010off200,mask2fit800GH]= draw_masks_helper(fh,mask2fit800GH,'msk_Ei800dir010off200',1);
plot(w2_800dir010off200); lz 0 1;keep_figure; %[output:9c810b22]
%
lp100of020 = line_proj([1,0,0],[0,1,0],'offset',[0,2,0]);
w2_800dir100off020 = cut(src800sym,lp100of020 ,[0,0.04,2],other_ranges800{:});
w2_800dir100off020.full_filename = [fname800,', w2_800dir100off020'];
fh = plot(w2_800dir100off020); lz 0 1; %[output:5c3e5396]
[w2_800dir100off020,mask2fit800GH]= draw_masks_helper(fh,mask2fit800GH,'msk_Ei800dir100off020',1);
plot(w2_800dir100off020); lz 0 1;keep_figure; %[output:5c3e5396]

w2e800GHoff110mid = sqw_op_bin_pixels({w2_800dir010off200,w2_800dir100off020}, ...
    @move_all_to_proj, ...
    {[lp010of200,lp100of020]}, ...
    lp010of200,[0,0.01,1],other_ranges800{:},'-combine');
plot(w2e800GHoff110mid);liny; lz 0 1;keep_figure; %[output:56764570]

hc.log_level = ll;
%%
% cuts in <010> direction offset 020 -- change orthogonal to axis; medium
% ff change
w2ei800off020dir010 = cut(w2e800GHoff110mid,[0,0.04,1],[65,4,335]) %[output:493c5f9b] %[output:64d0e217]
plot(w2ei800off020dir010); lz 0 0.5;keep_figure; %[output:5ac2946b]

GH_FFCutsFits = save_selected_cuts(GH_FFCutsFits,allJfitfileGH, ...
    'Ei800_off200GHmidFF',w2ei800off020dir010);

save(mask_res_file800GH,'mask2fit800GH')

